    changed=[]
    for k in set(old)&set(new):
        if old[k]!=new[k]:
            changed.append((k, old[k], new[k]))
    print(f"\n===== {name} +{len(added)} -{len(removed)} ~{len(changed)} =====")
    print("-- added --")
    for k in added:
        if any(s in k for s in ["documents","Profile","Comment","Document","core/src/Profiles","core/src/Contracts"]):
            print(" +", k, new[k][0], new[k][2])
    print("-- all added files --")
    files=sorted({k.split("|")[1] for k in added})
    for f in files:
